package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Real transactions cover cumulative money, concurrent adoption and actual shipped/unshipped source scope. */
class RefundAutomaticDecisionTest {
    RefundServiceTest f=new RefundServiceTest();RefundAutomaticDecision decision;RefundFlowAutomation flow;RefundGoodsTasks tasks;
    @BeforeAll static void start(){RefundServiceTest.start();}
    @BeforeEach void setup(){
        f.reset();f.db.update("UPDATE oms_order SET document_info=? WHERE id=?",encode(m("lines",Collections.singletonList(m("platform_oid","987654321012345679","goods_payment","25.00","payment_source","平台实付")))),f.order);
        decision=new RefundAutomaticDecision();decision.refunds=f.refunds;decision.workspace=f.workspace;decision.parcels=mock(RefundParcelPolicy.class);
        when(decision.parcels.get("VERIFY",1)).thenReturn(m("revision",1,"auto_create",1,"create_store_code","V","create_return_address","测试退回地址","create_return_contact","TEST"));
        tasks=new RefundGoodsTasks();tasks.refunds=f.refunds;f.workspace.goodsTasks=tasks;
        flow=new RefundFlowAutomation();flow.refunds=f.refunds;flow.catalog=mock(OrderCatalog.class);flow.workspace=f.workspace;
    }
    @AfterEach void clear(){f.clear();}
    long refund(String rid,int version,String fee,String status,String received,long quantity){Map<String,Object> src=f.source(version,fee,status),p=parse(text(src,"jdp_response"));p.put("refund_id",rid);p.put("good_status",received);p.put("num",quantity);src.put("refund_id",rid);src.put("jdp_response",encode(m("refund",p)));return f.convert(f.ingest(src));}
    Map<String,Object> policy(int small,int shipped,String limit){Map<String,Object> p=RefundFlowAutomation.defaults();p.putAll(m("enabled",1,"revision",0,"small_refund_enabled",small,"small_refund_limit",limit,"auto_shipped_cancel",shipped,"auto_intercept",1));flow.save("VERIFY",1,p,"test");return flow.policy("VERIFY",1);}
    @Test void merchantSmallRuleApprovesKeepWithoutInventoryOrReturnTasks(){f.shipped();long id=refund("9007199254740993",1,"2.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",1);assertTrue(decision.decide("VERIFY",id,policy(1,0,"5.00")));assertEquals("KEEP",f.refunds.business("VERIFY",id,false).get("goods_action"));assertEquals("OTHER",f.refunds.business("VERIFY",id,false).get("purpose"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void cumulativeSmallLimitIncludesPriorSuccessfulRefund(){f.shipped();long prior=refund("9007199254740993",1,"10.00","SUCCESS","BUYER_RECEIVED",1);f.workspace.review("VERIFY",prior,f.review(prior,"COMPENSATION","KEEP"),"test");long id=refund("9007199254740994",1,"10.01","WAIT_SELLER_AGREE","BUYER_RECEIVED",1);Map<String,Object> p=policy(1,0,"20.00");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p));assertEquals("PENDING",f.refunds.business("VERIFY",id,false).get("review_state"));}
    @Test void exactlyTheCumulativeSmallLimitIsAllowed(){f.shipped();long prior=refund("9007199254740993",1,"10.00","SUCCESS","BUYER_RECEIVED",1);f.workspace.review("VERIFY",prior,f.review(prior,"COMPENSATION","KEEP"),"test");long id=refund("9007199254740994",1,"10.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",1);assertTrue(decision.decide("VERIFY",id,policy(1,0,"20.00")));}
    @Test void partialOutboundBuildsCancelAndReturnFromOriginalSources(){f.shipped();f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=2");long id=refund("9007199254740993",1,"25.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",5);assertTrue(decision.decide("VERIFY",id,policy(0,1,"0.00")));assertEquals(3,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE action='CANCEL'",Integer.class));assertEquals(2,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE action='RETURN'",Integer.class));}
    @Test void earlierDifferenceReducesMoneyButNotGoodsReturnQuantity(){f.shipped();long prior=refund("9007199254740993",1,"2.00","SUCCESS","BUYER_RECEIVED",1);f.workspace.review("VERIFY",prior,f.review(prior,"DIFFERENCE","KEEP"),"test");long id=refund("9007199254740994",1,"23.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",5);assertTrue(decision.decide("VERIFY",id,policy(0,1,"0.00")));assertEquals(5,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE refund_id=?",Integer.class,id));assertEquals("23.00",text(f.refunds.business("VERIFY",id,false),"refund_fee"));}
    @Test void secondFullAmountCannotOverRefundAfterDifference(){f.shipped();long prior=refund("9007199254740993",1,"2.00","SUCCESS","BUYER_RECEIVED",1);f.workspace.review("VERIFY",prior,f.review(prior,"DIFFERENCE","KEEP"),"test");long id=refund("9007199254740994",1,"25.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",5);Map<String,Object> p=policy(0,1,"0.00");assertTrue(assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p)).getMessage().contains("剩余可退 23.00"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
    @Test void unknownWarehouseOutcomeNeverAutoAdopts(){f.shipped();f.db.update("UPDATE oms_order_shipment SET status='DISPATCHING'");long id=refund("9007199254740993",1,"25.00","WAIT_SELLER_AGREE","BUYER_NOT_RECEIVED",5);Map<String,Object> p=policy(0,1,"0.00");assertThrows(IllegalArgumentException.class,()->decision.decide("VERIFY",id,p));}
    @Test void concurrentSmallApprovalsShareOneOriginalSuborderBudget()throws Exception{f.shipped();long a=refund("9007199254740993",1,"15.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",1),b=refund("9007199254740994",1,"15.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",1);Map<String,Object> p=policy(1,0,"20.00");ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);List<Future<Boolean>> futures=new ArrayList<>();for(long id:new long[]{a,b})futures.add(pool.submit(()->{start.await();try{return decision.decide("VERIFY",id,p);}catch(IllegalArgumentException expected){return false;}}));start.countDown();int accepted=0;for(Future<Boolean> future:futures)if(future.get(20,TimeUnit.SECONDS))accepted++;assertEquals(1,accepted);assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund WHERE review_state='APPROVED'",Integer.class));}finally{pool.shutdownNow();}}
    @Test void approvedOnlyRefundCanQueueAutomaticReturnCreation(){f.shipped();long id=refund("9007199254740993",1,"25.00","WAIT_SELLER_AGREE","BUYER_RECEIVED",5);RefundReturnAutoCreate auto=new RefundReturnAutoCreate();auto.refunds=f.refunds;auto.policies=decision.parcels;f.workspace.autoCreate=auto;f.workspace.review("VERIFY",id,f.review(id,"CANCEL","RETURN"),"test");assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_auto_task WHERE refund_id=?",Integer.class,id));}
    @Test void outboundOvertakingUnexecutedCancellationReplansWithoutReleasingStock(){f.shipped();f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=0");long id=refund("9007199254740993",1,"25.00","WAIT_SELLER_AGREE","BUYER_NOT_RECEIVED",5);Map<String,Object> p=policy(0,1,"0.00"),input=f.review(id,"CANCEL","MIXED");long line=f.db.queryForObject("SELECT id FROM oms_order_line",Long.class);input.put("goods_tasks",Collections.singletonList(m("action","CANCEL","order_line_id",line,"quantity",5)));f.workspace.review("VERIFY",id,input,"自动售后规则");Map<String,Object> old=f.db.queryForMap("SELECT * FROM oms_refund_goods_task WHERE refund_id=?",id);f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=5");assertTrue(decision.replanOvertaken("VERIFY",old,f.refunds.business("VERIFY",id,false)));assertEquals("CANCELED",f.db.queryForObject("SELECT state FROM oms_refund_goods_task WHERE id=?",String.class,old.get("id")));assertEquals(5,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task WHERE refund_id=? AND action='INTERCEPT'",Integer.class,id));assertEquals(0,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line",Integer.class));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task WHERE command_json IS NOT NULL",Integer.class));}
    @Test void executedCancellationIntentNeverGetsReplacedByRaceFallback(){Map<String,Object> t=m("command_json","{}"),b=m();assertFalse(decision.replanOvertaken("VERIFY",t,b));}
}
